"""comtypes wrappers for a type library, generated by one process at a time.

``comtypes.client.GetModule("oleacc.dll")`` writes a Python wrapper into
``comtypes/gen`` the first time a venv needs it, and imports it every
time after. Two processes that need it at the same moment both write it.
The one that imports while the other is still writing gets a half file
and an exception. The UI modules guard that call with ``except Exception:
_AVAILABLE = False``, so the loser silently runs without UI automation for
its whole life.

That is how a full ``pytest -n 4`` on a fresh venv failed eight menu tests
on one worker, every time, and never on the next run of the same venv.
The four workers imported ``eda_agent.ui.menu`` together, and one of them
lost. On a fresh install the MCP server and the dashboard can race the
same way.

``get_module`` holds a lock file across processes while it calls
``GetModule``. Only one process writes; the others wait, then import the
finished file. It also tries again after a failure, since a wrapper left
half-written by a process that was killed is replaced on the next try.
"""
from __future__ import annotations

import contextlib
import importlib
import os
import tempfile
import time
from typing import Any, Iterator

#: How long to wait for another process to finish generating, in seconds.
LOCK_TIMEOUT_S = 120.0
#: Tries of ``GetModule`` before the last error is raised.
ATTEMPTS = 4


def lock_path() -> str:
    return os.path.join(tempfile.gettempdir(), "eda-agent-comtypes-gen.lock")


@contextlib.contextmanager
def _locked(path: str, timeout: float = LOCK_TIMEOUT_S) -> Iterator[None]:
    """An exclusive lock on ``path`` across processes (and across threads,
    since each call opens its own handle). Without a way to lock, the body
    runs unlocked rather than not at all."""
    try:
        handle = open(path, "a+b")
    except OSError:
        yield
        return
    try:
        if os.name == "nt":
            import msvcrt
            deadline = time.monotonic() + timeout
            while True:
                try:
                    handle.seek(0)
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    break
                except OSError:
                    if time.monotonic() >= deadline:
                        raise TimeoutError(f"{path} stayed locked for {timeout:g} s")
                    time.sleep(0.05)
            try:
                yield
            finally:
                handle.seek(0)
                with contextlib.suppress(OSError):
                    msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    finally:
        handle.close()


def get_module(type_library: str, attempts: int = ATTEMPTS) -> Any:
    """``comtypes.client.GetModule(type_library)``, made safe when several
    processes may generate the same wrapper at once. Raises the last
    error when every attempt failed."""
    import comtypes.client

    last: BaseException | None = None
    for attempt in range(max(1, attempts)):
        try:
            with _locked(lock_path()):
                return comtypes.client.GetModule(type_library)
        except TimeoutError:
            raise
        except Exception as exc:  # noqa: BLE001 - comtypes raises many kinds
            last = exc
            importlib.invalidate_caches()
            time.sleep(0.1 * (attempt + 1))
    assert last is not None
    raise last
